#!/usr/bin/env node

/**
 * WoG era modules — build every shipped asset from the Codex art masters in
 * tmp/gen/wog-era/*.png (generated by tmp/gen/wog-era/gen-batch.ps1).
 *
 * Codex paints ART ONLY; frames, titles, rules text and glyphs are composed
 * here deterministically from real card frames (the repo's card-builder rule):
 *  - map tokens: the two moving bosses + the Wandering Teacher (+ the Mithril
 *    resource icon), background keyed out if Codex ignored the transparency
 *    request;
 *  - the Mithril Mine Field-Override hex art (512×512 full-bleed, clipped to
 *    the hex by the board like every override);
 *  - the two moving boss cards (bosses/roaming_behemoth.webp,
 *    bosses/lich_sovereign.webp) in the raid-boss card style;
 *  - six Mithril war-machine faces on the real First Aid Tent frame;
 *  - nine Skill Combo ability faces on the real Tactics ability frame (the
 *    printed crown divider between the Basic and Expert halves is kept).
 * Missing masters are skipped and listed — nothing is faked.
 *
 * Usage: node scripts/build-wog-era-art.mjs
 * Layout dry run: WOG_ERA_MASTERS=<dir> WOG_ERA_OUT=<dir> writes elsewhere.
 */

import { existsSync } from "node:fs";
import { mkdir, readFile, rename, rm } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ASSETS = path.join(ROOT, "public", "assets");
const MASTERS = process.env.WOG_ERA_MASTERS
  ? path.resolve(process.env.WOG_ERA_MASTERS)
  : path.join(ROOT, "tmp", "gen", "wog-era");
const GLYPHS = path.join(ROOT, "scripts", "card-glyphs");
// Templates are always read from public/assets; outputs may be redirected.
const OUT_ASSETS = process.env.WOG_ERA_OUT ? path.resolve(process.env.WOG_ERA_OUT) : ASSETS;
const OUT_ERA = path.join(OUT_ASSETS, "wog-era");

const CARD_WIDTH = 743;
const CARD_HEIGHT = 1040;
const GOLD = "#eadb8f";
const LIGHT = "#eee5c8";
const DARK = "#2d211a";
const WEBP_QUALITY = 94;

const missing = [];
const built = [];

function master(name) {
  const file = path.join(MASTERS, `${name}.png`);
  if (!existsSync(file)) {
    missing.push(name);
    return null;
  }
  return file;
}

function escapeXml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

function mulberry32(seed) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let value = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

/** A feathered, softly mottled leather patch that hides the template's copy. */
function leatherPatch(width, height, rgb, seed, feather = 4) {
  const random = mulberry32(seed);
  const pixels = Buffer.alloc(width * height * 4);
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const index = (y * width + x) * 4;
      const grain = Math.round((random() - 0.5) * 12);
      const mottling = Math.round(3 * Math.sin(x / 25 + seed) + 2 * Math.sin(y / 32 + seed / 4));
      const vignette = Math.round(((x / width - 0.5) ** 2 + (y / height - 0.5) ** 2) * -8);
      for (let channel = 0; channel < 3; channel += 1) {
        pixels[index + channel] = Math.max(0, Math.min(255, rgb[channel] + grain + mottling + vignette));
      }
      const edge = Math.min(x, y, width - 1 - x, height - 1 - y);
      pixels[index + 3] = feather === 0 ? 255 : Math.round(255 * Math.min(1, edge / feather));
    }
  }
  return { input: pixels, raw: { width, height, channels: 4 } };
}

async function glyphDataUri(name) {
  const source = (await readFile(path.join(GLYPHS, `${name}.svg`), "utf8")).replaceAll("currentColor", GOLD);
  return `data:image/svg+xml;base64,${Buffer.from(source).toString("base64")}`;
}

/** Greedy word wrap by an approximate Georgia-bold glyph width. */
function wrap(text, fontSize, maxWidth) {
  const words = text.split(/\s+/);
  const lines = [];
  let line = "";
  for (const word of words) {
    const next = line ? `${line} ${word}` : word;
    if (next.length * fontSize * 0.5 > maxWidth && line) {
      lines.push(line);
      line = word;
    } else {
      line = next;
    }
  }
  if (line) lines.push(line);
  return lines;
}

async function writeWebp(pipeline, destination) {
  await mkdir(path.dirname(destination), { recursive: true });
  const temporary = `${destination}.tmp.webp`;
  await pipeline.webp({ quality: WEBP_QUALITY, effort: 6 }).toFile(temporary);
  await rm(destination, { force: true });
  await rename(temporary, destination);
  built.push(path.relative(ROOT, destination));
}

// ---------------------------------------------------------------------------
// Map tokens
// ---------------------------------------------------------------------------

/**
 * Key out a flat / gradient background by flood-filling from the border with a
 * colour tolerance (Codex often ignores "transparent background"). Images that
 * already carry real alpha keep it.
 */
async function keyedSprite(source) {
  const { data, info } = await sharp(source).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const { width, height } = info;
  const alphaAt = (x, y) => data[(y * width + x) * 4 + 3];
  const cornersTransparent = [alphaAt(0, 0), alphaAt(width - 1, 0), alphaAt(0, height - 1), alphaAt(width - 1, height - 1)].every(
    (alpha) => alpha < 16
  );
  if (!cornersTransparent) {
    const seen = new Uint8Array(width * height);
    const queue = [];
    const colourAt = (index) => [data[index * 4], data[index * 4 + 1], data[index * 4 + 2]];
    for (let x = 0; x < width; x += 1) queue.push(x, (height - 1) * width + x);
    for (let y = 0; y < height; y += 1) queue.push(y * width, y * width + width - 1);
    const seeds = queue.map(colourAt);
    const near = (a, b) => Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) + Math.abs(a[2] - b[2]) < 60;
    let head = 0;
    while (head < queue.length) {
      const index = queue[head];
      const seed = seeds[head] ?? colourAt(index);
      head += 1;
      if (seen[index]) continue;
      const colour = colourAt(index);
      if (!near(colour, seed)) continue;
      seen[index] = 1;
      data[index * 4 + 3] = 0;
      const x = index % width;
      const y = (index - x) / width;
      const push = (nx, ny) => {
        if (nx >= 0 && ny >= 0 && nx < width && ny < height) {
          const next = ny * width + nx;
          if (!seen[next]) {
            queue.push(next);
            seeds.push(colour);
          }
        }
      };
      push(x + 1, y);
      push(x - 1, y);
      push(x, y + 1);
      push(x, y - 1);
    }
  }
  return sharp(data, { raw: { width, height, channels: 4 } }).png().toBuffer();
}

async function buildSprite(masterName, destinationName, size) {
  const source = master(masterName);
  if (!source) return;
  const keyed = await keyedSprite(source);
  const trimmed = await sharp(keyed).trim({ threshold: 1 }).png().toBuffer();
  await mkdir(OUT_ERA, { recursive: true });
  await writeWebp(
    sharp(trimmed).resize(size, size, { fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 } }),
    path.join(OUT_ERA, destinationName)
  );
}

/** Full-bleed square hex art (the board clips it to the hex, "slice"). */
async function buildHexArt(masterName, destinationName) {
  const source = master(masterName);
  if (!source) return;
  await writeWebp(
    sharp(source).resize(512, 512, { fit: "cover", position: "centre" }),
    path.join(OUT_ERA, destinationName)
  );
}

// ---------------------------------------------------------------------------
// Moving boss card (raid-boss card style)
// ---------------------------------------------------------------------------

async function buildBossCard(masterName, name, subtitle, fileName) {
  const source = master(masterName);
  if (!source) return;
  const art = await sharp(source)
    .resize(CARD_WIDTH, CARD_HEIGHT, { fit: "cover", position: "centre" })
    .modulate({ saturation: 0.95, brightness: 0.95 })
    .png()
    .toBuffer();
  const frame = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${CARD_WIDTH}" height="${CARD_HEIGHT}">
    <defs>
      <radialGradient id="v" cx="50%" cy="45%" r="75%">
        <stop offset="60%" stop-color="#000" stop-opacity="0"/>
        <stop offset="100%" stop-color="#000" stop-opacity="0.7"/>
      </radialGradient>
      <linearGradient id="plate" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#1a120c" stop-opacity="0.92"/>
        <stop offset="100%" stop-color="#0c0806" stop-opacity="0.96"/>
      </linearGradient>
    </defs>
    <rect width="100%" height="100%" fill="url(#v)"/>
    <rect x="14" y="14" width="${CARD_WIDTH - 28}" height="${CARD_HEIGHT - 28}" rx="22" fill="none" stroke="#c9a653" stroke-width="5"/>
    <rect x="26" y="26" width="${CARD_WIDTH - 52}" height="${CARD_HEIGHT - 52}" rx="16" fill="none" stroke="#7a5f28" stroke-width="2"/>
    <path d="M40 90 Q40 40 90 40" fill="none" stroke="#e1c46b" stroke-width="4"/>
    <path d="M${CARD_WIDTH - 40} 90 Q${CARD_WIDTH - 40} 40 ${CARD_WIDTH - 90} 40" fill="none" stroke="#e1c46b" stroke-width="4"/>
    <rect x="62" y="855" width="${CARD_WIDTH - 124}" height="118" rx="10" fill="url(#plate)" stroke="#c9a653" stroke-width="3"/>
    <g font-family="Georgia, 'Times New Roman', serif" text-anchor="middle">
      <text x="${CARD_WIDTH / 2}" y="905" font-size="37" font-weight="700" fill="#f3e3b0" letter-spacing="1.5">${escapeXml(name)}</text>
      <text x="${CARD_WIDTH / 2}" y="946" font-size="23" font-style="italic" fill="#d9c79a">${escapeXml(subtitle)}</text>
    </g>
  </svg>`);
  await writeWebp(
    sharp(art).composite([{ input: frame }]),
    path.join(OUT_ASSETS, "bosses", fileName)
  );
}

