async function buildMithrilMachine(card, seed) {
  const source = master(`mithril-${card.slug}`);
  if (!source) return;
  const art = await sharp(source)
    .resize(611, 569, { fit: "cover", position: "centre" })
    .modulate({ saturation: 0.94, brightness: 0.96 })
    .sharpen({ sigma: 0.45 })
    .png()
    .toBuffer();
  const titleSize = card.title.length > 22 ? 34 : card.title.length > 16 ? 40 : 46;
  const fontSize = card.text.length > 120 ? 21 : 23;
  const lineHeight = fontSize + 10;
  const lines = wrap(card.text, fontSize, 500);
  const startY = 905 - ((lines.length - 1) * lineHeight) / 2;
  const permanent = await glyphDataUri("permanent");
  const copy = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${CARD_WIDTH}" height="${CARD_HEIGHT}">
    <g font-family="Georgia, 'Times New Roman', serif" paint-order="stroke" stroke="${DARK}" stroke-width="3" fill="${LIGHT}" dominant-baseline="middle" font-weight="700">
      <text x="371.5" y="112" text-anchor="middle" font-size="${titleSize}" fill="${GOLD}">${escapeXml(card.title)}</text>
      <text x="371.5" y="773" text-anchor="middle" font-size="26" fill="#cfe9ff">Forged with 6 Mithril</text>
      ${lines
        .map((line, index) => `<text x="395" y="${startY + index * lineHeight}" text-anchor="middle" font-size="${fontSize}">${escapeXml(line)}</text>`)
        .join("\n")}
    </g>
    <image href="${permanent}" x="84" y="826" width="50" height="25"/>
  </svg>`);
  await writeWebp(
    sharp(path.join(ASSETS, "war_machines-first_aid_tent.webp"))
      .resize(CARD_WIDTH, CARD_HEIGHT, { fit: "fill" })
      .composite([
        { ...leatherPatch(609, 88, [65, 45, 35], seed, 4), left: 67, top: 67 },
        { input: art, left: 66, top: 161 },
        { ...leatherPatch(609, 56, [59, 42, 33], seed + 1, 3), left: 67, top: 745 },
        { ...leatherPatch(609, 169, [40, 29, 24], seed + 2, 4), left: 67, top: 813 },
        { input: copy }
      ]),
    path.join(OUT_ASSETS, `war_machines-${card.slug}-mithril.webp`)
  );
}

