/** The emblem master faded into the leather (no box edge). */
async function preparedEmblem(source) {
  const width = 470;
  const height = 330;
  const image = await sharp(source)
    .resize(width, height, { fit: "cover", position: "centre" })
    .modulate({ saturation: 0.96, brightness: 0.95 })
    .sharpen({ sigma: 0.4 })
    .png()
    .toBuffer();
  const mask = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">
    <defs><radialGradient id="fade" cx="50%" cy="50%" r="62%">
      <stop offset="0%" stop-color="white" stop-opacity="1"/>
      <stop offset="68%" stop-color="white" stop-opacity="1"/>
      <stop offset="100%" stop-color="white" stop-opacity="0"/>
    </radialGradient></defs>
    <rect width="100%" height="100%" fill="url(#fade)"/>
  </svg>`);
  return sharp(image).ensureAlpha().composite([{ input: mask, blend: "dest-in" }]).png().toBuffer();
}

async function buildCombo(card, seed) {
  const source = master(`combo-${card.slug}`);
  if (!source) return;
  const emblem = await preparedEmblem(source);
  const glyph = await glyphDataUri(card.glyph);
  const basicLines = wrap(card.basic, 23, 520);
  const expertLines = wrap(card.expert, 23, 520);
  const basicStart = 560 - ((basicLines.length - 1) * 34) / 2;
  const expertStart = 872 - ((expertLines.length - 1) * 34) / 2;
  const titleSize = card.title.length > 14 ? 44 : 50;
  const lineSvg = (lines, start) =>
    lines.map((line, index) => `<text x="${index === 0 ? 400 : 371.5}" y="${start + index * 34}" text-anchor="middle" font-size="23">${escapeXml(line)}</text>`).join("\n");
  const copy = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${CARD_WIDTH}" height="${CARD_HEIGHT}">
    <g font-family="Georgia, 'Times New Roman', serif" paint-order="stroke" stroke="${DARK}" stroke-width="3" fill="${LIGHT}" dominant-baseline="middle" font-weight="700">
      <text x="371.5" y="430" text-anchor="middle" font-size="${titleSize}" fill="${GOLD}">${escapeXml(card.title)}</text>
      <text x="371.5" y="478" text-anchor="middle" font-size="21" font-style="italic" fill="#d9c79a">Combo: ${escapeXml(card.combo)}</text>
      ${lineSvg(basicLines, basicStart)}
      ${lineSvg(expertLines, expertStart)}
    </g>
    <image href="${glyph}" x="92" y="${basicStart - 15}" width="30" height="30"/>
    <image href="${glyph}" x="92" y="${expertStart - 15}" width="30" height="30"/>
  </svg>`);
  await writeWebp(
    sharp(path.join(ASSETS, "abilities-tactics.webp"))
      .resize(CARD_WIDTH, CARD_HEIGHT, { fit: "fill" })
      .composite([
        { ...leatherPatch(615, 638, [65, 44, 34], seed), left: 64, top: 67 },
        { ...leatherPatch(615, 187, [58, 40, 32], seed + 1), left: 64, top: 785 },
        { input: emblem, left: 136, top: 73 },
        { input: copy }
      ]),
    path.join(OUT_ASSETS, `abilities-combo-${card.slug}.webp`)
  );
}

